# One-time bootstrap (separate state):
resource "aws_s3_bucket" "tf_state" {
  bucket = "acme-terraform-state"
}
resource "aws_s3_bucket_versioning" "tf_state" {
  bucket = aws_s3_bucket.tf_state.id
  versioning_configuration { status = "Enabled" }
}
resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"
  attribute { name = "LockID"; type = "S" }
}

resource "aws_s3_bucket" "data" {
  bucket = "acme-data-bucket"
}

# terraform import aws_s3_bucket.data acme-data-bucket
# terraform plan   <- must report "No changes" before this is considered done

// push model -- CI holds the keys
az aks get-credentials --resource-group prod-rg --name prod-aks
kubectl apply -f k8s/production/

// pull model -- the in-cluster agent holds nothing but outbound Git access
// (ArgoCD/Flux, running inside the cluster, on its own schedule)
git fetch origin main
// diff live cluster state against what's now in Git
// apply only if they differ, using in-cluster RBAC

# consumer side -- one line replaces 200+ lines of owned pipeline YAML
jobs:
  run-shared-pipeline:
    uses: my-org/pipeline-templates/.github/workflows/build-test-scan.yml@v1
    secrets:
      NPM_TOKEN: ${{ secrets.NPM_TOKEN }}

# branch protection -- makes the required job structurally unskippable
# Settings -> Branches -> Branch protection rule
# Require status checks to pass before merging:
#   ✓ run-shared-pipeline / build-test-scan

# renovate.json -- propagates version bumps without manual edits
{
  "packageRules": [
    { "matchManagers": ["github-actions"], "matchPackageNames": ["my-org/pipeline-templates"], "schedule": ["before 9am on monday"] }
  ]
}

questions.code:
variable "cloud" {
  type = string
}

variable "name" {
  type = string
}

variable "cidr_block" {
  type    = string
  default = "10.20.0.0/16"
}

variable "azure_region" {
  type    = string
  default = "eastus"
}

resource "azurerm_resource_group" "this" {
  count    = var.cloud == "azure" ? 1 : 0
  name     = "rg-${var.name}"
  location = var.azure_region
}

resource "azurerm_virtual_network" "this" {
  name                = "vnet-${var.name}"
  address_space       = [var.cidr_block]
  location            = azurerm_resource_group.this[0].location
  resource_group_name = azurerm_resource_group.this[0].name
}

resource "aws_vpc" "this" {
  count      = var.cloud == "aws" ? 1 : 0
  cidr_block = var.cidr_block
  tags       = { Name = var.name }
}

output "network_id" {
  value = var.cloud == "azure" ? azurerm_virtual_network.this[0].id : aws_vpc.this[0].id
}

